// L9a text: UTF-8 helpers and Python 3.11 (Unicode 14.0.0) string predicates.
//
// Production's normaliser is Python; every str method it calls (isalpha,
// isdigit, isspace, upper, casefold, strip, split) is reproduced here from
// tables generated by the reference interpreter itself
// (tools/l9a/gen_unicode_tables.py -> unicode_tables.inc), so the C++ answer is
// Python's answer code point for code point.
#pragma once

#include <cstddef>
#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

namespace kt2n::text {

// ---- UTF-8 -----------------------------------------------------------------
// Decodes one code point at s[i]; advances i. Input must be valid UTF-8
// (validated once at the API boundary with valid_utf8()).
char32_t decode(std::string_view s, size_t& i);
void append_utf8(std::string& out, char32_t cp);
std::u32string to_u32(std::string_view s);
std::string to_utf8(std::u32string_view s);
bool valid_utf8(std::string_view s);
size_t cp_len(std::string_view s);  // number of code points

// ---- Python str predicates (per code point) --------------------------------
bool py_isalpha(char32_t c);
bool py_isdigit(char32_t c);
bool py_isalnum(char32_t c);
bool py_isspace(char32_t c);
bool py_latin_name(char32_t c);  // unicodedata.name(c).startswith("LATIN")
bool py_is_upper_char(char32_t c);
bool py_is_lower_char(char32_t c);
bool py_is_title_char(char32_t c);
inline bool py_isascii(char32_t c) { return c < 0x80; }

// ---- Python str methods ----------------------------------------------------
std::u32string py_upper(std::u32string_view s);
std::u32string py_casefold(std::u32string_view s);
std::string py_casefold(std::string_view s);
bool py_str_isupper(std::u32string_view s);  // str.isupper()
bool py_str_isalpha(std::u32string_view s);  // str.isalpha() ("" -> false)
bool py_str_isascii(std::string_view s);
// strip()/rstrip()/lstrip() with no argument (Unicode whitespace).
std::string py_strip(std::string_view s);
std::string py_rstrip(std::string_view s);
std::string py_lstrip(std::string_view s);
// strip(chars) / rstrip(chars) / lstrip(chars) with an explicit set.
std::string py_strip_chars(std::string_view s, std::u32string_view chars);
std::string py_rstrip_chars(std::string_view s, std::u32string_view chars);
std::string py_lstrip_chars(std::string_view s, std::u32string_view chars);
// split() with no argument: runs of Unicode whitespace, no empty strings.
std::vector<std::string> py_split_ws(std::string_view s);
// split(sep) with an explicit separator (empty strings kept).
std::vector<std::string> py_split(std::string_view s, std::string_view sep);
std::string py_replace(std::string_view s, std::string_view from, std::string_view to);
std::string join(const std::vector<std::string>& parts, std::string_view sep);

// re.IGNORECASE equivalents of an ASCII letter, as Python's re module has them
// ("s" also matches U+017F, "k" U+212A, "i" U+0130/U+0131).
std::u32string py_ignorecase_set(char letter);

// Moses (sacremoses perluniprops) classes.
bool moses_is_alpha(char32_t c);
bool moses_is_sc(char32_t c);
bool moses_is_cjk(char32_t c);

}  // namespace kt2n::text
